const requester = $input.first().json;
const body = $('Webhook - Assign Contact Owner').first().json.body || {};

if (!requester.valid) {
  throw new Error('Invalid session.');
}

if (requester.role !== 'admin') {
  throw new Error('Only admins can assign contact owners.');
}

const contactId = parseInt(body.contact_id, 10);
const ownerIdRaw = body.owner_id;
const ownerId = (ownerIdRaw === null || ownerIdRaw === undefined || ownerIdRaw === '')
  ? null
  : parseInt(ownerIdRaw, 10);

if (!Number.isInteger(contactId)) {
  throw new Error('"contact_id" must be an integer.');
}
if (ownerId !== null && !Number.isInteger(ownerId)) {
  throw new Error('"owner_id" must be an integer or null.');
}

return [{ json: { contactId, ownerId } }];

const requesterName = $('Execute Workflow: Verify Session (US1)').first().json.user.name || 'Someone';
const requesterId = $('Execute Workflow: Verify Session (US1)').first().json.userId;
const payload = $('Validate Admin & Payload').first().json;
const contact = $('Update Contact Owner').first().json;
const oldOwnerName = $('Look Up Old Owner').first().json.old_owner_name || 'Unassigned';
const newOwnerName = $input.first().json.new_owner_name || 'Unassigned';
const contactName = `${contact.first_name || ''} ${contact.last_name || ''}`.trim() || 'Unknown Contact';

if (oldOwnerName === newOwnerName) {
  // A no-op query that always returns exactly one row — a downstream
  // Postgres node that yields zero output items would silently stop the
  // rest of this chain (owner notification DM etc.), so "SELECT 1;" is
  // used instead of an insert with a WHERE-false-style skip.
  return [{ json: { sqlQuery: 'SELECT 1;', queryParams: [] } }];
}

const summary = `${requesterName} transferred ownership of "${contactName}" from ${oldOwnerName} to ${newOwnerName}`;
const detail = JSON.stringify({ from: oldOwnerName, to: newOwnerName });

const sqlQuery = 'INSERT INTO entity_activity_log (entity_type, entity_id, category, subtype, summary, detail, actor_id, actor_name) VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7,$8) RETURNING id;';
const queryParams = ['contact', payload.contactId, 'system_audit', 'ownership_change', summary, detail, requesterId, requesterName];

return [{ json: { sqlQuery, queryParams } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Contact not found.');
}
return [{ json: { success: true, contact: result.json } }];

