  throw new Error('"color" must be a hex code like #3B82F6.');
}

return [{ json: { targetUserId, color } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('User not found.');
}
return [{ json: { success: true, user: result.json } }];

const payload = $('Validate Admin & Payload').first().json;
const requesterId = $('Execute Workflow: Verify Session (US1)').first().json.userId;
const contact = $('Update Contact Owner').first().json;
const ownerId = payload.ownerId;
// Only notify when the deal is actually handed to someone else — not on
// unassign (ownerId null) or an admin assigning themselves.
const notify = !!ownerId && ownerId !== requesterId;
const dmKey = notify ? [requesterId, ownerId].sort((a, b) => a - b).join('-') : null;
const contactName = `${contact.first_name || ''} ${contact.last_name || ''}`.trim() || 'a contact';
const movedEvents = Number(contact.moved_events || 0);
return [{ json: { notify, dmKey, requesterId, ownerId, contactId: payload.contactId, contactName, movedEvents } }];

