const requester = $input.first().json;
const body = $('Webhook - Update User Theme').first().json.body || {};

if (!requester.valid) {
  throw new Error('Invalid session.');
}

const targetUserId = parseInt(body.user_id, 10);
if (!Number.isInteger(targetUserId)) {
  throw new Error('"user_id" must be an integer.');
}

// Admins can re-theme anyone; everyone else can only style their own account.
if (requester.role !== 'admin' && requester.userId !== targetUserId) {
  throw new Error('You can only change your own theme.');
}

const hex = /^#[0-9A-Fa-f]{6}$/;
const fields = ['header_color', 'main_color', 'accent_color'];
const values = {};
for (const field of fields) {
  const raw = body[field];
  // Any of the three may be explicitly null to reset that slot back
  // to the app default — only a present, non-null value is validated.
  if (raw === null || raw === undefined) { values[field] = null; continue; }
  const v = raw.toString().trim();
  if (!hex.test(v)) {
    throw new Error(`"${field}" must be a hex code like #3B82F6.`);
  }
  values[field] = v;
}

return [{ json: { targetUserId, ...values } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('User not found.');
}
return [{ json: { success: true, user: result.json } }];

const requester = $input.first().json;
const body = $('Webhook - Update Notification Preferences').first().json.body || {};

if (!requester.valid) {
  throw new Error('Invalid session.');
}

// Users only ever manage their own notification preferences — unlike color,
// there's no admin-on-behalf-of-someone-else case for this.
const targetUserId = requester.userId;

const allowedKeys = ['email', 'chat', 'tasks_due'];
const prefs = body.preferences && typeof body.preferences === 'object' ? body.preferences : {};
const cleaned = {};
for (const key of allowedKeys) {
  if (key in prefs) cleaned[key] = !!prefs[key];
}
if (Object.keys(cleaned).length === 0) {
  throw new Error('No valid preference keys provided.');
}

return [{ json: { targetUserId, preferences: JSON.stringify(cleaned) } }];

const result = $input.first();
