const body = $('Webhook - Upload Avatar').first().json.body || {};
const photo = body.photo || {};
const dataUrl = photo.url || '';

const m = /^data:([^;,]+)?(?:;[^,]*)?,(.*)$/s.exec(dataUrl);
if (!m) throw new Error('"photo.url" must be a base64 data URL.');
const [, mimeType, base64] = m;

if (!mimeType || !mimeType.startsWith('image/')) {
  throw new Error('Photo must be an image file.');
}
if (base64.length > 7000000) {
  throw new Error('Photo is too large (max ~5MB).');
}

return [{
  json: { requesterId },
  binary: {
    data: {
      data: base64,
      mimeType,
      fileName: photo.name || 'avatar.jpg'
    }
  }
}];

