const bcrypt = require('bcryptjs');
const requester = $('Execute Workflow: Verify Session (US8)').first().json;
const passwordHash = $input.first().json.password_hash;
const body = $('Webhook - Change Password').first().json.body || {};

if (!requester.valid) throw new Error('Invalid session.');

const currentPassword = body.current_password || '';
const newPassword = body.new_password || '';

if (!currentPassword || !newPassword) {
  throw new Error('Current and new password are required.');
}
if (newPassword.length < 10) {
  throw new Error('New password must be at least 10 characters.');
}
if (newPassword.length > 72) {
  throw new Error('New password must be 72 characters or fewer.');
}

const isValid = bcrypt.compareSync(currentPassword, passwordHash);
if (!isValid) {
  throw new Error('Current password is incorrect.');
}

const salt = bcrypt.genSaltSync(10);
const newHash = bcrypt.hashSync(newPassword, salt);

return [{ json: { targetUserId: requester.userId, newHash } }];

